def _conversion_lineage(
    *,
    intended_hda_ids: set[str],
    resolved_hda_ids: set[str],
    history_id: str,
    fetch_dataset: Callable[[str], Mapping[str, Any]] | None,
    fetch_job: Callable[[str], Mapping[str, Any]] | None,
) -> list[dict[str, Any]]:
